cat artifacts/runs/final-primary/sources/annapolis-courier/application.md; cat artifacts/runs/final-primary/sources/annapolis-courier/payroll-register.csv; cat artifacts/runs/final-primary/sources/annapolis-courier/field-notes.md; python3 - <<'PY'
import csv,collections
from pathlib import Path
from decimal import Decimal as D
p=Path('artifacts/runs/final-primary/sources/annapolis-courier')
r=list(csv.DictReader((p/'route-log.csv').open()));w=list(csv.DictReader((p/'weekly-payroll.csv').open()))
for person in ('AC-E04','AC-E05'):
 groups=collections.Counter();amount=collections.defaultdict(lambda:D(0)); examples={}
 for week in [x for x in w if x['employee_id']==person]:
  rides=[x for x in r if x['ride_along_id']==person and week['week_start']<=x['date']<=week['week_end']]
  n=len({x['date'] for x in rides});code='T-610' if n>=2 else 'C-110';groups[code]+=1;amount[code]+=D(week['gross_pay'])
  if n not in examples:examples[n]=(week,rides)
 print(person,'weeks',dict(groups),'pay',dict(amount))
 for n,(week,rides) in sorted(examples.items()):
  print('EXAMPLE ride days=',n,'weekly payroll=',week,'route rows=',rides)
PY

