from pathlib import Path
import json,markdown
p=Path('docs/learner-review-state.json');state=json.loads(p.read_text())
changes={
 'severn-homebuilders':('choice recorded','Accept proposed correction rather than original application, superseding the earlier choice. Learner cites insurance-certificate, site-signin-log and subcontractor-payment records (supplied files: insurance-certificates.csv, site-signin-log.csv, subcontractor-payments.csv), after reviewing them. Kent’s identity/full-period coverage remains open; no missing coverage is established by learner acceptance.'),
 'annapolis-courier':('revision pending','Revision of the earlier two-fifths choice requested; learner acknowledges that it conflicts with Nadia’s whole-week rule. Replacement allocation and supporting records are pending confirmation. The earlier USD18976.88 alternative remains historical. The company-rule table and CSV retain USD22808.75 of Lena’s wages in T-610 (employer T-610 USD176694.95, C-110 USD107820.45).')}
for e,(status,new) in changes.items():
 old=state['employers'][e]['display']
 for report in [Path('deliverables/audit-report.md'),Path('deliverables/audit-questions.md')]:
  text=report.read_text();assert text.count(old)==1,(e,report);report.write_text(text.replace(old,new))
 state['employers'][e]['status']=status;state['employers'][e]['display']=new
p.write_text(json.dumps(state,indent=2,ensure_ascii=False)+'\n')
for name in ('audit-report','audit-questions'):
 p=Path('artifacts/verification')/(name+'.html');header=p.read_text().split('<body>',1)[0]
 p.write_text(header+'<body>'+markdown.markdown(Path('deliverables',name+'.md').read_text(),extensions=['tables'])+'</body></html>')
for e in changes:print(e,state['employers'][e]['status'],state['employers'][e]['display'])
